import React, { useState, useEffect, useMemo } from 'react';

// --- Helper Components & Icons ---

const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', cursor: 'pointer' }}>
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="12" y1="16" x2="12" y2="12"></line>
        <line x1="12" y1="8" x2="12.01" y2="8"></line>
    </svg>
);

const EditIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#495057' }}>
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
    </svg>
);


// --- Main Component ---

export default function PerStudentAllocationTab({ onAllocationChange }) {
    // --- State Management ---
    const [numberOfStudents, setNumberOfStudents] = useState(100);
    const [adminLoading, setAdminLoading] = useState(0.0); // Stored as a decimal, e.g., 0.005 for 0.5%
    const [details, setDetails] = useState('');
    const [allocations, setAllocations] = useState([
        { role: 'Subject Coordinator', marking: 0, consultation: 0.0025, coordination: 0.00125 },
        { role: 'Assistant subject coordinator', marking: 0, consultation: 0, coordination: 0.00375 },
        { role: 'Exam marker', marking: 0.01, consultation: 0, coordination: 0 },
        { role: 'Tutor', marking: 0.01, consultation: 0.0025, coordination: 0 }
    ]);
    const [errors, setErrors] = useState({});

    // --- Memoized Calculations ---
    const BASE_RATE_PER_25 = 0.03; // Fixed base rate of 3%

    const totalRatePer25 = useMemo(() => {
        return BASE_RATE_PER_25 + adminLoading;
    }, [adminLoading]);

    const totalPerStudentAllocation = useMemo(() => {
        if (numberOfStudents > 0) {
            return (numberOfStudents / 25) * totalRatePer25;
        }
        return 0;
    }, [numberOfStudents, totalRatePer25]);

    const currentDistributedSum = useMemo(() => {
        return allocations.reduce((total, item) => {
            return total + (item.marking || 0) + (item.consultation || 0) + (item.coordination || 0);
        }, 0);
    }, [allocations]);

    // --- Effects ---

    // Effect to notify parent component of the total allocation change
    useEffect(() => {
        if (onAllocationChange) {
            onAllocationChange(totalPerStudentAllocation);
        }
    }, [totalPerStudentAllocation, onAllocationChange]);

    // Effect to run validations when inputs change
    useEffect(() => {
        const newErrors = {};

        // 1. Number of students validation
        if (!Number.isInteger(numberOfStudents) || numberOfStudents <= 0) {
            newErrors.numberOfStudents = 'Number of students must be a positive whole number.';
        }

        // 2. Admin loading validation
        if (adminLoading < 0 || adminLoading > 0.01) {
            newErrors.adminLoading = 'Administrative loading must be between 0% and 1%.';
        }

        // 3. Details validation
        if (adminLoading > 0 && !details.trim()) {
            newErrors.details = 'Details are required to justify the administrative loading claim.';
        }

        // 4. Distribution table sum validation
        if (currentDistributedSum > totalRatePer25) {
             newErrors.table = `Maximum allocation exceeded. The sum of distributions (${(currentDistributedSum * 100).toFixed(3)}%) cannot be more than the total rate of ${(totalRatePer25 * 100).toFixed(3)}%.`;
        }

        setErrors(newErrors);
    }, [numberOfStudents, adminLoading, details, currentDistributedSum, totalRatePer25]);

    // --- Event Handlers ---

    const handleAllocationChange = (index, category, value) => {
        const newAllocations = [...allocations];
        const parsedValue = parseFloat(value);
        // Convert percentage input to decimal for storage
        newAllocations[index][category] = isNaN(parsedValue) ? 0 : parsedValue / 100;
        setAllocations(newAllocations);
    };

    const handleAdminLoadingChange = (e) => {
        const val = parseFloat(e.target.value);
        setAdminLoading(isNaN(val) ? 0 : val / 100);
    };

    return (
        <div style={styles.container}>
            {/* --- Top Level Inputs --- */}
            <div style={styles.inputGrid}>
                <div style={styles.inputGroup}>
                    <label style={styles.label} htmlFor="totalAllocation">Per-student Allocation <InfoIcon /></label>
                    <input style={styles.input} id="totalAllocation" type="text" value={`${(totalPerStudentAllocation * 100).toFixed(1)}%`} readOnly />
                </div>
                <div style={styles.inputGroup}>
                    <label style={styles.label} htmlFor="numStudents">Number of students</label>
                    <input style={styles.input} id="numStudents" type="number" value={numberOfStudents} onChange={(e) => setNumberOfStudents(parseInt(e.target.value, 10) || 0)} />
                     {errors.numberOfStudents && <span style={styles.errorText}>{errors.numberOfStudents}</span>}
                </div>
                 <div style={styles.inputGroup}>
                    <label style={styles.label} htmlFor="adminLoading">Administrative loading per 25 students <InfoIcon /></label>
                    <input style={styles.input} id="adminLoading" type="number" step="0.1" value={(adminLoading * 100).toFixed(3)} onChange={handleAdminLoadingChange} />
                     {errors.adminLoading && <span style={styles.errorText}>{errors.adminLoading}</span>}
                </div>
            </div>

            <div style={{...styles.inputGroup, marginTop: '1rem'}}>
                <label style={styles.label} htmlFor="details">Details</label>
                <textarea style={styles.textarea} id="details" placeholder="If a claim is made, provide details." value={details} onChange={(e) => setDetails(e.target.value)}></textarea>
                {errors.details && <span style={styles.errorText}>{errors.details}</span>}
            </div>

            {/* --- Distribution Table --- */}
            <div style={styles.tableContainer}>
                 <div style={styles.tableHeader}>
                    <h3 style={styles.tableTitle}>Per 25 students</h3>
                    <InfoIcon />
                </div>
                 {errors.table && <span style={{...styles.errorText, marginBottom: '1rem', display: 'block'}}>{errors.table}</span>}
                <table style={styles.table}>
                    <thead>
                        <tr>
                            <th style={styles.th}>Actions</th>
                            <th style={styles.th}>Staff Role</th>
                            <th style={styles.th}>Marking</th>
                            <th style={styles.th}>Consultation</th>
                            <th style={styles.th}>Coordination</th>
                        </tr>
                    </thead>
                    <tbody>
                        {allocations.map((item, index) => (
                            <tr key={index}>
                                <td style={styles.td}><EditIcon /></td>
                                <td style={styles.td}>{item.role}</td>
                                <td style={styles.td}><input type="number" step="0.01" style={styles.tableInput} value={(item.marking * 100).toFixed(4)} onChange={(e) => handleAllocationChange(index, 'marking', e.target.value)} /></td>
                                <td style={styles.td}><input type="number" step="0.01" style={styles.tableInput} value={(item.consultation * 100).toFixed(4)} onChange={(e) => handleAllocationChange(index, 'consultation', e.target.value)} /></td>
                                <td style={styles.td}><input type="number" step="0.01" style={styles.tableInput} value={(item.coordination * 100).toFixed(4)} onChange={(e) => handleAllocationChange(index, 'coordination', e.target.value)} /></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div style={styles.buttonContainer}>
                <button style={styles.saveButton}>Save</button>
            </div>
        </div>
    );
}

// --- Styles ---
const styles = {
    container: { backgroundColor: '#fff', padding: '2rem', borderRadius: '8px', border: '1px solid #dee2e6' },
    inputGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '1.5rem' },
    inputGroup: { display: 'flex', flexDirection: 'column', gap: '0.5rem' },
    label: { color: '#495057', fontWeight: '500', fontSize: '0.9rem', display: 'flex', alignItems: 'center', gap: '0.5rem' },
    input: { padding: '0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem' },
    textarea: { padding: '0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem', minHeight: '80px', resize: 'vertical' },
    errorText: { color: '#dc3545', fontSize: '0.8rem', marginTop: '0.25rem' },
    tableContainer: { marginTop: '2rem' },
    tableHeader: { display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' },
    tableTitle: { margin: 0, fontSize: '1.1rem', color: '#343a40' },
    table: { width: '100%', borderCollapse: 'collapse' },
    th: { backgroundColor: '#f8f9fa', padding: '0.75rem', textAlign: 'left', border: '1px solid #dee2e6', color: '#495057', fontWeight: '600', fontSize: '0.9rem' },
    td: { padding: '0.75rem', textAlign: 'left', border: '1px solid #dee2e6', color: '#343a40' },
    tableInput: { width: '90%', padding: '0.5rem', border: '1px solid #dee2e6', borderRadius: '4px' },
    buttonContainer: { display: 'flex', justifyContent: 'flex-end', marginTop: '2rem' },
    saveButton: { backgroundColor: '#28a745', color: 'white', padding: '0.6rem 1.5rem', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '500' }
};
